<!--
ServiceTreePanelComponent.vue

Full single-file component. 
We added debugging lines in toggleNode(...) and getCatChildren(...), 
plus a mounted() hook that logs the entire leftPanel data in the active locale.

No other features are changed. 
-->

<template>
  <div class="service-tree-panel">
    <h4>{{ $t('sidebar.governmentServices') }}</h4>

    <ul>
      <li v-for="(node, index) in nodes" :key="index">
        <div class="node-label" @click="toggleNode(node)">
          <span v-if="hasChildren(node.catKey)" class="toggle-icon">
            {{ node.expanded ? '▼' : '▶' }}
          </span>
          <span class="node-name">{{ getCatName(node.catKey) }}</span>
        </div>

        <ul
          v-if="node.expanded && hasChildren(node.catKey)"
          class="child-list"
        >
          <li
            v-for="(childName, cIndex) in getCatChildren(node.catKey)"
            :key="cIndex"
          >
            <div class="node-label" @click.stop="selectCategory(childName)">
              <span class="toggle-icon placeholder"></span>
              <span class="node-name">{{ childName }}</span>
            </div>
          </li>
        </ul>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: 'ServiceTreePanelComponent',

  data() {
    return {
      // The 12 top-level categories, each with a catKey like 'cat1', 'cat2', ...
      nodes: [
        { catKey: 'cat1', expanded: false },
        { catKey: 'cat2', expanded: false },
        { catKey: 'cat3', expanded: false },
        { catKey: 'cat4', expanded: false },
        { catKey: 'cat5', expanded: false },
        { catKey: 'cat6', expanded: false },
        { catKey: 'cat7', expanded: false },
        { catKey: 'cat8', expanded: false },
        { catKey: 'cat9', expanded: false },
        { catKey: 'cat10', expanded: false },
        { catKey: 'cat11', expanded: false },
        { catKey: 'cat12', expanded: false }
      ]
    }
  },

  mounted() {
    // Debug: confirm which locale is active in THIS component
    console.log("ServiceTreePanel - mounted. Active locale:", this.$i18n.locale)

    // Log the entire leftPanel data for the current locale
    const leftPanelData = this.$i18n.getLocaleMessage(this.$i18n.locale)?.leftPanel
    console.log("ServiceTreePanel - leftPanel data in", this.$i18n.locale, ":", leftPanelData)

    // If leftPanel is an object, enumerate cat1..cat12
    if (leftPanelData && typeof leftPanelData === 'object') {
      Object.keys(leftPanelData).forEach(k => {
        console.log(`ServiceTreePanel - found key "${k}" with name:`, leftPanelData[k].name, 
                    "and children:", leftPanelData[k].children)
      })
    } else {
      console.log("ServiceTreePanel - no leftPanel object found in locale:", this.$i18n.locale)
    }
  },

  methods: {
    toggleNode(node) {
      console.log("toggleNode clicked for catKey:", node.catKey, "locale:", this.$i18n.locale)
      node.expanded = !node.expanded
    },

    selectCategory(childName) {
      this.$emit('selectCategory', childName)
    },

    getCatName(catKey) {
      return this.$t(`leftPanel.${catKey}.name`)
    },

    getCatChildren(catKey) {
      console.log("getCatChildren for", catKey, "in locale:", this.$i18n.locale)
      const result = this.$t(`leftPanel.${catKey}.children`, { returnObjects: true })
      console.log(`Children for ${catKey}:`, result)
      return result
    },

    hasChildren(catKey) {
      const arr = this.getCatChildren(catKey)
      return Array.isArray(arr) && arr.length > 0
    }
  }
}
</script>

<style scoped>
.service-tree-panel {
  margin-bottom: 20px;
}

.service-tree-panel h4 {
  margin-bottom: 8px;
  font-weight: 600;
  color: #333;
}

ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.node-label {
  display: flex;
  align-items: center;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.node-label:hover {
  background-color: #f0f0f0;
}

.toggle-icon {
  width: 20px;
  text-align: center;
  margin-right: 4px;
  color: #666;
  font-size: 12px;
}

.toggle-icon.placeholder {
  visibility: hidden; /* Align child items with the parent toggle icon */
}

.node-name {
  flex: 1;
  color: #333;
}

.child-list {
  margin-left: 20px;
  border-left: 1px dashed #ccc;
  padding-left: 8px;
  margin-top: 2px;
}
</style>

