import { createRouter, createWebHistory } from 'vue-router'
import DashboardView from '@/views/DashboardView.vue' // adjust path if needed

const routes = [
  // Route for /dashboard
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: DashboardView
  },
  // Optional: redirect root (/) to /dashboard
  {
    path: '/',
    redirect: '/dashboard'
  },
  // Catch-all: if user goes anywhere else, also go to /dashboard
  {
    path: '/:pathMatch(.*)*',
    redirect: '/dashboard'
  }
]

const router = createRouter({
  history: createWebHistory(),
  routes
})

export default router

