<template>
  <div v-if="visible" class="analytics-dialog">
    <div class="overlay" @click="closeDialog"></div>
    <div class="dialog-content">
      <h2>Data Analytics & Insights</h2>
      <p>Below are some usage stats and feedback summaries.</p>

      <div class="stats-section">
        <h3>Usage Stats</h3>
        <ul>
          <li>Total Users: {{ analyticsData.totalUsers }}</li>
          <li>Total Chats: {{ analyticsData.totalChats }}</li>
          <li>Average Rating: {{ analyticsData.averageRating }}</li>
        </ul>
      </div>

      <div class="feedback-section">
        <h3>User Feedback Samples</h3>
        <ul>
          <li v-for="(item, index) in analyticsData.feedbackSamples" :key="index">
            "{{ item.comment }}" - Rating: {{ item.rating }}
          </li>
        </ul>
      </div>

      <div class="actions">
        <button @click="closeDialog">Close</button>
      </div>
    </div>
  </div>
</template>

<script>
import axios from 'axios'

export default {
  name: 'AnalyticsDialog',
  props: {
    visible: Boolean
  },
  data() {
    return {
      analyticsData: {
        totalUsers: 0,
        totalChats: 0,
        averageRating: 0,
        feedbackSamples: []
      }
    }
  },
  watch: {
    visible(newVal) {
      if (newVal) {
        this.fetchAnalytics()
      }
    }
  },
  methods: {
    fetchAnalytics() {
      axios.get('/api/admin/analytics')
        .then(res => {
          this.analyticsData = res.data
        })
        .catch(err => {
          console.error('Error fetching analytics:', err)
        })
    },
    closeDialog() {
      this.$emit('close')
    }
  }
}
</script>

