.analytics-dialog {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  z-index: 9999;
}
.overlay {
  position: absolute;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.5);
}
.dialog-content {
  position: relative;
